SELECT uniq(session_person_id) AS unique_users, NULL AS previous_unique_users, sum(filtered_pageview_count) AS total_filtered_pageview_count, NULL AS previous_total_filtered_pageview_count, uniq(session_id) AS unique_sessions, NULL AS previous_unique_sessions, avg(session_duration) AS avg_duration_s, NULL AS previous_avg_duration_s, avg(is_bounce) AS bounce_rate, NULL AS previous_bounce_rate FROM (SELECT any(if(not(empty(events__override.distinct_id)), events__override.person_id, events.person_id)) AS session_person_id, events__session.session_id AS session_id, min(events__session.`$start_timestamp`) AS start_timestamp, any(events__session.`$session_duration`) AS session_duration, countIf(or(equals(events.event, '$pageview'), equals(events.event, '$screen'))) AS filtered_pageview_count, any(events__session.`$is_bounce`) AS is_bounce FROM events_json AS events LEFT JOIN (SELECT toString(reinterpretAsUUID(bitOr(bitShiftLeft(raw_sessions.session_id_v7, 64), bitShiftRight(raw_sessions.session_id_v7, 64)))) AS session_id, min(toTimeZone(raw_sessions.min_timestamp, 'UTC')) AS `$start_timestamp`, dateDiff('second', min(toTimeZone(raw_sessions.min_timestamp, 'UTC')), max(toTimeZone(raw_sessions.max_timestamp, 'UTC'))) AS `$session_duration`, if(equals(uniqMerge(raw_sessions.pageview_uniq), 0), NULL, not(or(greater(uniqMerge(raw_sessions.pageview_uniq), 1), greater(uniqMerge(raw_sessions.autocapture_uniq), 0), greaterOrEquals(dateDiff('second', min(toTimeZone(raw_sessions.min_timestamp, 'UTC')), max(toTimeZone(raw_sessions.max_timestamp, 'UTC'))), 10)))) AS `$is_bounce`, raw_sessions.session_id_v7 AS session_id_v7 FROM raw_sessions WHERE and(equals(raw_sessions.team_id, TEAM_ID), greaterOrEquals(fromUnixTimestamp(intDiv(toUInt64(bitShiftRight(raw_sessions.session_id_v7, 80)), 1000)), minus(assumeNotNull(toDateTime('DATE_FROM 00:00:00', 'UTC')), toIntervalDay(3))), lessOrEquals(fromUnixTimestamp(intDiv(toUInt64(bitShiftRight(raw_sessions.session_id_v7, 80)), 1000)), plus(assumeNotNull(toDateTime('DATE_TO 23:59:59', 'UTC')), toIntervalDay(3)))) GROUP BY raw_sessions.session_id_v7) AS events__session ON equals(toUInt128(toUUIDOrNull(events.properties.`$session_id`)), events__session.session_id_v7) LEFT OUTER JOIN (SELECT argMax(person_distinct_id_overrides.person_id, person_distinct_id_overrides.version) AS person_id, person_distinct_id_overrides.distinct_id AS distinct_id FROM person_distinct_id_overrides WHERE equals(person_distinct_id_overrides.team_id, TEAM_ID) GROUP BY person_distinct_id_overrides.distinct_id HAVING equals(argMax(person_distinct_id_overrides.is_deleted, person_distinct_id_overrides.version), 0) SETTINGS optimize_aggregation_in_order=1) AS events__override ON equals(events.distinct_id, events__override.distinct_id) WHERE and(equals(events.team_id, TEAM_ID), and(isNotNull(events.properties.`$session_id`), or(equals(events.event, '$pageview'), equals(events.event, '$screen')), or(and(greaterOrEquals(toTimeZone(events.timestamp, 'UTC'), assumeNotNull(toDateTime('DATE_FROM 00:00:00', 'UTC'))), lessOrEquals(toTimeZone(events.timestamp, 'UTC'), assumeNotNull(toDateTime('DATE_TO 23:59:59', 'UTC')))), 0), 1)) GROUP BY session_id HAVING or(and(greaterOrEquals(start_timestamp, assumeNotNull(toDateTime('DATE_FROM 00:00:00', 'UTC'))), lessOrEquals(start_timestamp, assumeNotNull(toDateTime('DATE_TO 23:59:59', 'UTC')))), 0)) LIMIT 50000
